function __oa331(oldL,toL){/* pkgOPA (ASK 331, ruling 461): Option A, one test, read by code. A refused cure stays UNCURED but is not counted when the judge's line and the corrected line carry the same grade word and every count field is identical (CONCEDED LINKS, CHALLENGER CONCEDED LINKS, DEFENSE STANDING, CHALLENGE STANDING, n, w, k, L, c). A line that cannot be read on either side fails (it is counted, as today). */
 try{const N=s=>String(s==null?'':s).replace(/\\+"/g,'"').replace(/\\n/g,' ').replace(/[*_`]+/g,'').replace(/\s+/g,' ').trim();
 const G=/(?:^|--|—|–|:|\|)\s*(DEFENDER LINK BROKEN|CHALLENGER LINK BROKEN|UNDERDETERMINED|STANDS|BROKEN|HELD|MEETS|MISSES|FAILS|UNPROVEN|VOID|COUNTED|SPARED|UNEXHIBITED|CONCEDED|WITHDRAWN|RETRACTED|SELF-SUPPORTED|PROP-DEPENDENT|COLLAPSED)\b/;
 const rd=s=>{const t=N(s).replace(/^RESTATED\s*:\s*/i,'');const b=t.replace(/["“][^"”]*["”]/g,' " ');const g=b.match(G);if(!g)return null;const c=[];
  for(const m of b.matchAll(/\b(CHALLENGER\s+)?CONCEDED LINKS\s*:\s*(\d+)/g))c.push((m[1]?'CCL':'DCL')+'='+m[2]);for(const m of b.matchAll(/\b(DEFENSE|CHALLENGE) STANDING\s*:\s*([A-Z][A-Z-]+)/g))c.push(m[1]+'='+m[2]);for(const m of b.matchAll(/(?<![A-Za-z])([nwkLc])\s*=\s*(\d+)/g))c.push(m[1]+'='+m[2]);
  return {g:g[1],c:c.sort().join(',')};};
 if(!N(oldL)||!N(toL))return {ok:false,why:'a line is empty'};const a=rd(oldL),b=rd(toL);if(!a||!b)return {ok:false,why:'no grade word could be read in '+(!a?'the judge\'s line':'the corrected line')};
 if(a.g!==b.g)return {ok:false,why:'the grade differs ('+a.g+' to '+b.g+')'};if(a.c!==b.c)return {ok:false,why:'a count field differs ('+(a.c||'none')+' to '+(b.c||'none')+')'};
 return {ok:true,why:'the grade ('+a.g+') and every count field'+(a.c?' ('+a.c+')':'')+' are identical in the judge\'s line and the corrected line'};}catch(e){return {ok:false,why:'reading error: '+String(e&&e.message||e).slice(0,120)};}}
function __oaRaw(seat){/* pkgOPA: the seat's own verdict text, from the bodies this node reads (panel or alternate); none found means the line cannot be shown to be replaceable */
 const src=[];try{if(typeof PASS!=='undefined'&&PASS&&Array.isArray(PASS.bodies))src.push(PASS.bodies);}catch(e){}for(const n of ['Panel Cure Check','Alt Seated','R2 Alt Seated']){try{const j=$(n);if(j&&j.isExecuted){const b=j.first().json.bodies;if(Array.isArray(b))src.push(b);}}catch(e){}}
 for(const B of src)for(const x of B){try{const p=(typeof x==='string'?JSON.parse(x):x).payload;if(p&&p.judge_seat===seat)return String(p.verdict_raw||'');}catch(e){}}return null;}
function __oaSkip(it,a,row,seat){/* pkgOPA: true when the refused cure is off the drv_uncured tally under ruling 461: a CHANGE TO, the judge's line found in the seat's own text (so the change can replace it), and the one test passed. Otherwise false: counted as today. The row keeps UNCURED and says why. */
 if(!a||a.ans!=='CHANGE'||!it)return false;if(/^\s*(?:NOT HELD|RETRACTED|WITHDRAWN)\b/i.test(String(a.to||'')))return false;
 const nl=s=>String(s==null?'':s).replace(/\\+"/g,'"').replace(/\\n/g,'\n').replace(/[*_`]+/g,'').replace(/[ \t]+/g,' ').trim();const raw=__oaRaw(seat);if(raw==null)return false;const L0=nl(it.line);if(!L0||!nl(raw).split('\n').some(l=>l.trim()===L0))return false;
 const r=__oa331(it.line,a.to);if(!r.ok)return false;
 if(row&&!/OPTION A \(ASK 331/.test(String(row.cure_reason||'')))row.cure_reason=String(row.cure_reason||'')+' | OPTION A (ASK 331, ruling 461): '+r.why+'; the judge\'s line is in its text, so the change replaces it; the row stays UNCURED and is off the drv_uncured tally; it removes no seat';return true;}
